```java
@Override
@Transactional
public ServiceResult adjudicateFinishEvidence(String raceId, AdjudicateFinishEvidenceRequest request) {
    List<String> evidenceIds = List.copyOf(request.evidenceIds());
    List<String> finalOrder = List.copyOf(request.finalOrder());
    return withIdempotency(request.requestId(), "ADJUDICATE_FINISH_EVIDENCE",
            orderedParams("raceId", raceId, "adjudicationId", request.adjudicationId(),
                    "evidenceIds", evidenceIds, "finalOrder", finalOrder,
                    "operator", request.operator(), "expectedVersion", request.expectedVersion()),
            () -> {
                RaceRow race = requireOpenRace(raceId, request.expectedVersion());
                // 证据ID去重校验
                Set<String> distinctIds = new HashSet<>(evidenceIds);
                if (distinctIds.size() != evidenceIds.size())
                    throw new UnprocessableEntityException("裁决请求包含重复证据ID");
                List<FinishEvidenceRow> evidenceList = new ArrayList<>();
                for (String evidenceId : evidenceIds) {
                    FinishEvidenceRow evidence = repository.findFinishEvidence(evidenceId)
                            .orElseThrow(() -> new NotFoundException("证据不存在: " + evidenceId));
                    if (!evidence.raceId().equals(raceId))
                        throw new NotFoundException("证据不属于该赛事: " + evidenceId);
                    evidenceList.add(evidence);
                }
                long finishTimeMs = evidenceList.get(0).finishTimeMs();
                Set<String> candidates = new TreeSet<>(evidenceList.get(0).suggestedOrder());
                for (FinishEvidenceRow evidence : evidenceList) {
                    if (evidence.status() != EvidenceStatus.PENDING)
                        throw new UnprocessableEntityException("证据已裁决或已撤回: " + evidence.evidenceId());
                    if (evidence.finishTimeMs() != finishTimeMs)
                        throw new UnprocessableEntityException("证据不属于同一计时组: " + evidence.evidenceId());
                    if (!new TreeSet<>(evidence.suggestedOrder()).equals(candidates))
                        throw new UnprocessableEntityException("证据候选人不一致: " + evidence.evidenceId());
                }
                // 全部候选人仍有效：选手存在、计时未变、未被取消资格
                List<RunnerRow> runners = repository.findRunners(raceId);
                Map<String, RunnerRow> byBib = ...;
                List<PenaltyRow> penalties = repository.findPenalties(raceId);
                Set<String> disqualified = ...;
                for (String bib : candidates) {
                    RunnerRow runner = byBib.get(bib);
                    if (runner == null) throw new UnprocessableEntityException("候选人已不存在: " + bib);
                    if (runner.finishTimeMs() == null || runner.finishTimeMs() != finishTimeMs)
                        throw new UnprocessableEntityException("候选人计时已变更: " + bib);
                    if (disqualified.contains(bib)) throw new UnprocessableEntityException("候选人已被取消资格: " + bib);
                }
                // 裁决名次无重复且不遗漏：finalOrder 必须为候选集合的全排列
                if (finalOrder.size() != candidates.size())
                    throw new UnprocessableEntityException("裁决名次顺序必须覆盖全部候选人");
                Set<String> finalSet = new TreeSet<>(finalOrder);
                if (finalSet.size() != finalOrder.size())
                    throw new UnprocessableEntityException("裁决名次顺序重复候选人");
                if (!finalSet.equals(candidates))
                    throw new UnprocessableEntityException("裁决名次顺序遗漏候选人或包含非候选人");
                long now = clock.millis();
                bumpVersion(race, request.expectedVersion());
                int newVersion = request.expectedVersion() + 1;
                for (FinishEvidenceRow evidence : evidenceList) {
                    if (repository.markEvidenceAdjudicated(evidence.evidenceId(), now) == 0)
                        throw new UnprocessableEntityException("证据状态已变化: " + evidence.evidenceId());
                }
                FinishAdjudicationRow adjudication = new FinishAdjudicationRow(0L, request.adjudicationId(),
                        raceId, finishTimeMs, evidenceIds, finalOrder, request.operator(), newVersion, now);
                try {
                    repository.insertFinishAdjudication(adjudication);
                } catch (DuplicateKeyException ex) {
                    throw new ConflictException("裁决ID已存在: " + request.adjudicationId());
                }
                FinishAdjudicationRow saved = repository.findFinishAdjudication(request.adjudicationId()).orElseThrow();
                return ServiceResult.created(ResponseMapper.toAdjudicationResponse(saved));
            });
}
